  overflow: hidden;
  border-right: 3px solid black;

  /* Use the variable for width and steps */
  width: calc(var(--chars) * 1ch);
  animation:
    typing 3s steps(var(--chars)) forwards,
    blink 0.5s infinite step-end;
}

@keyframes typing {
  from {
    width: 0;
  }
}

@keyframes blink {
  50% {
    border-color: transparent;
  }
}</code></pre>
